:root {
  --color-bg: #1e1e2f;
  --color-surface: #2a2a40;
  --color-primary: #6c5ce7;
  --color-primary-hover: #7d6ff0;
  --color-accent: #00cec9;
  --color-text: #f0f0f5;
  --color-text-muted: #a0a0b8;
  --card-size: 80px;
  --gap: 12px;
  --radius: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--color-bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--color-text);
  padding: 16px;
}

.game-container {
  width: 100%;
  max-width: 520px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
}

.game-header {
  text-align: center;
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 4px;
}

.subtitle {
  color: var(--color-text-muted);
  font-size: 1rem;
}

.stats-bar {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.stat {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.stat-label {
  font-size: 1rem;
  color: var(--color-text-muted);
}

.stat-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-accent);
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text);
  background-color: var(--color-primary);
  border: none;
  border-radius: var(--radius);
  padding: 12px 24px;
  cursor: pointer;
  transition: background-color 0.15s, transform 0.1s;
}

.btn:hover {
  background-color: var(--color-primary-hover);
}

.btn:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
}

.game-board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--gap);
  width: 100%;
  perspective: 1000px;
}

.card {
  position: relative;
  aspect-ratio: 1 / 1;
  cursor: pointer;
  border: none;
  background: none;
  padding: 0;
  border-radius: var(--radius);
  transform-style: preserve-3d;
  transition: transform 0.4s ease;
}

.card:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.card.flipped {
  transform: rotateY(180deg);
}

.card-face {
  position: absolute;
  inset: 0;
  border-radius: var(--radius);
  backface-visibility: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: 700;
}

.card-front {
  background-color: var(--color-surface);
  border: 2px solid var(--color-primary);
  color: var(--color-primary);
}

.card-back {
  background-color: var(--card-color, var(--color-surface));
  transform: rotateY(180deg);
  border: 2px solid rgba(255, 255, 255, 0.2);
}

.card.matched {
  cursor: default;
}

.card.matched .card-back {
  box-shadow: 0 0 0 3px var(--color-accent);
}

.win-message {
  text-align: center;
  padding: 20px;
  background-color: var(--color-surface);
  border-radius: var(--radius);
  border: 2px solid var(--color-accent);
  width: 100%;
}

.win-message p:first-child {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.win-message p:last-child {
  color: var(--color-text-muted);
}

@media (max-width: 420px) {
  :root {
    --gap: 8px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .stat-value {
    font-size: 1.25rem;
  }
  .btn {
    padding: 10px 18px;
  }
}

(function () {
  'use strict';

  const COLORS = [
    '#e74c3c', '#3498db', '#2ecc71', '#f1c40f',
    '#9b59b6', '#e67e22', '#1abc9c', '#e84393'
  ];

  const boardEl = document.getElementById('game-board');
  const moveCounterEl = document.getElementById('move-counter');
  const newGameBtn = document.getElementById('new-game-btn');
  const winMessageEl = document.getElementById('win-message');
  const winStatsEl = document.getElementById('win-stats');

  let deck = [];
  let flippedCards = [];
  let moves = 0;
  let matchedPairs = 0;
  let lockBoard = false;

  function shuffle(array) {
    for (let i = array.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [array[i], array[j]] = [array[j], array[i]];
    }
    return array;
  }

  function createDeck() {
    const cards = [];
    COLORS.forEach((color, index) => {
      cards.push({ id: index, color });
      cards.push({ id: index, color });
    });
    return shuffle(cards);
  }

  function renderBoard() {
    boardEl.innerHTML = '';
    deck.forEach((cardData, index) => {
      const card = document.createElement('button');
      card.type = 'button';
      card.className = 'card';
      card.dataset.id = cardData.id;
      card.dataset.index = index;
      card.setAttribute('aria-label', 'Hidden card ' + (index + 1));
      card.innerHTML =
        '<span class="card-face card-front" aria-hidden="true">?</span>' +
        '<span class="card-face card-back" aria-hidden="true"></span>';
      card.querySelector('.card-back').style.backgroundColor = cardData.color;
      card.addEventListener('click', () => handleCardClick(card));
      boardEl.appendChild(card);
    });
  }

  function handleCardClick(card) {
    if (lockBoard || card.classList.contains('flipped') || card.classList.contains('matched')) {
      return;
    }

    card.classList.add('flipped');
    card.setAttribute('aria-label', 'Revealed card ' + (Number(card.dataset.index) + 1));
    flippedCards.push(card);

    if (flippedCards.length === 2) {
      moves++;
      moveCounterEl.textContent = moves;
      checkMatch();
    }
  }

  function checkMatch() {
    const [cardA, cardB] = flippedCards;
    const isMatch = cardA.dataset.id === cardB.dataset.id;

    if (isMatch) {
      cardA.classList.add('matched');
      cardB.classList.add('matched');
      cardA.disabled = true;
      cardB.disabled = true;
      cardA.setAttribute('aria-label', 'Matched card');
      cardB.setAttribute('aria-label', 'Matched card');
      matchedPairs++;
      flippedCards = [];
      if (matchedPairs === COLORS.length) {
        showWin();
      }
    } else {
      lockBoard = true;
      setTimeout(() => {
        cardA.classList.remove('flipped');
        cardB.classList.remove('flipped');
        cardA.setAttribute('aria-label', 'Hidden card ' + (Number(cardA.dataset.index) + 1));
        cardB.setAttribute('aria-label', 'Hidden card ' + (Number(cardB.dataset.index) + 1));
        flippedCards = [];
        lockBoard = false;
      }, 800);
    }
  }

  function showWin() {
    winStatsEl.textContent = 'Completed in ' + moves + ' moves!';
    winMessageEl.hidden = false;
    winMessageEl.focus();
  }

  function resetGame() {
    deck = createDeck();
    flippedCards = [];
    moves = 0;
    matchedPairs = 0;
    lockBoard = false;
    moveCounterEl.textContent = '0';
    winMessageEl.hidden = true;
    renderBoard();
  }

  newGameBtn.addEventListener('click', resetGame);

  resetGame();
})();
